import { CommonModule } from '@angular/common';
import { Component, effect, EffectRef, HostBinding, HostListener, inject, Injector, Input, model, OnChanges, Signal, SimpleChanges, TemplateRef } from '@angular/core';
import { Params, RouterModule } from '@angular/router';
import { MessageConfig, MessageModule } from 'espd-common/i18n';
import { IconDirective } from 'espd-common/icon';
import { ButtonConfig, ButtonContent } from './button.model';

type StartsWithIcon = `icon-${string}`;
type BooleanField = keyof Pick<ButtonConfig, 'secondary' | 'small' | 'rounded' | 'disabled' | 'loading'>;

@Component({
	selector: 'espd-button',
	templateUrl: './button.component.html',
	imports: [
		CommonModule,
		RouterModule,
		IconDirective,
		MessageModule
	],
	styleUrls: ['./button.component.scss']
})
export class ButtonComponent implements OnChanges {

	private injector = inject(Injector);

	/*
		Note: when adding new inputs, make sure to add them to the config object as well and update the onChanges method
	*/

	@Input()
	public type: 'button' | 'submit' = 'button';

	@Input()
	public color: 'primary' | 'success' | 'warning' | 'danger' | 'info' | 'dark' | 'link' | 'close' | 'remove' | 'edit' | StartsWithIcon = 'primary';

	/**
	 * @deprecated Use secondary instead
	 */
	@Input()
	public outline = false;

	public secondary = model(false);
	public small = model(false);
	public disabled = model(false);
	public loading = model(false);
	public rounded = model(false);

	@Input()
	@HostBinding('class.block')
	public block = false;

	@Input()
	public disableHoverTextDecoration = false;

	@Input()
	public routerPath?: string;

	@Input()
	public queryParams?: Params | null;

	@Input()
	public path?: string;

	@Input()
	public target: '_self' | '_blank' = '_self';

	@Input()
	public config?: ButtonConfig;

	private effects: Partial<Record<BooleanField, EffectRef>> = {};

	@HostListener('click')
	public onClick(): void {
		this.config?.click?.();
	}

	public get classes(): string {
		return `btn btn-${(this.outline || this.secondary()) ? 'outline-' : ''}${this.color}
		${this.block ? 'btn-block' : ''} ${this.small() ? 'btn-sm' : ''}
		${this.isRounded ? 'rounded-circle' : ''} ${this.icon ? 'btn-icon' : ''}`;
	}

	public get icon(): string | null {
		if (this.color === 'remove') return 'rvt-close-circle-solid';
		if (this.color === 'edit') return 'rvt-pencil';
		return this.getIconSuffix();
	}

	public get iconMesssage(): string | null {
		if (this.color === 'remove') return 'common.remove';
		if (this.color === 'edit') return 'common.edit';
		return null;
	}

	public get hasTextConfig(): boolean {
		return this.isTextual(this.content);
	}

	public get textConfig(): string | MessageConfig {
		return this.isTextual(this.content)
			? this.content
			: '';
	}

	public get contentTemplate(): TemplateRef<any> | null {
		return this.isTemplate(this.content)
			? this.content
			: null;
	}

	private get content(): ButtonContent | undefined {
		return this.config?.text ?? this.config?.content;
	}

	private get isRounded(): boolean {
		return this.rounded() || !!this.icon;
	}

	public ngOnChanges(changes: SimpleChanges): void {
		if (changes.config?.currentValue) {
			const config = changes.config.currentValue as ButtonConfig;
			this.type = config.type ?? 'button';
			this.color = config.color ?? 'primary';
			(['secondary', 'small', 'disabled', 'loading', 'rounded'] as BooleanField[])
				.forEach(field => this.assignBooleanConfigOption(field));
			this.routerPath = config.routerPath;
			this.queryParams = config.queryParams;
			this.path = config.path;
			this.target = config.target ?? '_self';
		}
	}

	private assignBooleanConfigOption(configKey: BooleanField) {
		const configValue = this.config![configKey] ??= false;

		if (this.isBooleanSignal(configValue)) {
			this.effects[configKey]?.destroy();
			this.effects[configKey] = effect(() => this[configKey].set(configValue()), { injector: this.injector });
		} else {
			this[configKey].set(configValue);
		}
	}

	private isBooleanSignal(value: boolean | Signal<boolean>): value is Signal<boolean> {
		return typeof value !== 'boolean';
	}

	private getIconSuffix(): string | null {
		if ((this.color || '').startsWith('icon-')) {
			return this.color.substring(5) || null;
		} else {
			return null;
		}
	}

	private isTextual(content: string | MessageConfig | TemplateRef<any> | undefined): content is string | MessageConfig {
		return !!content && (typeof content === 'string' || Object.prototype.hasOwnProperty.call(content, 'key'));
	}

	private isTemplate(content: string | MessageConfig | TemplateRef<any> | undefined): content is TemplateRef<any> {
		return !!content && content instanceof TemplateRef;
	}
}