import { CommonModule } from '@angular/common';
import { Component, HostListener, Input, OnChanges, SimpleChanges } from '@angular/core';
import { Params, RouterModule } from '@angular/router';
import { MessageModule } from 'espd-common/i18n';
import { ColorButtonConfig } from './color-button.model';

@Component({
	selector: 'espd-color-button',
	templateUrl: './color-button.component.html',
	imports: [
		CommonModule,
		RouterModule,
		MessageModule
	],
	styleUrls: ['./color-button.component.scss']
})
export class ColorButtonComponent implements OnChanges {

	/*
		Note: when adding new inputs, make sure to add them to the config object as well and update the onChanges method
	*/

	@Input()
	public type: 'button' | 'submit' = 'button';

	@Input()
	public colors: string[] = ['#000000', '#808080'];

	@Input()
	public disabled = false;

	@Input()
	public loading = false;

	@Input()
	public disableHoverTextDecoration = false;

	@Input()
	public routerPath?: string;

	@Input()
	public queryParams?: Params | null;

	@Input()
	public path?: string;

	@Input()
	public config?: ColorButtonConfig;

	public styles: any = {};

	constructor() {
		this.styles = {
			leftStyle: {},
			rightStyle: {}
		}
		this.updateColors();
	}

	public readonly classes = 'btn d-flex swatch';

	public ngOnChanges(changes: SimpleChanges): void {
		if (changes.config?.currentValue) {
			this.type = this.config!.type ?? this.type;
			this.colors = this.config!.colors ?? this.colors;
			this.disabled = this.config!.disabled ?? this.disabled;
			this.loading = this.config!.loading ?? this.loading;
			this.routerPath = this.config!.routerPath ?? this.routerPath;
			this.queryParams = this.config!.queryParams ?? this.queryParams;
			this.path = this.config!.path ?? this.path;
		}
		this.updateColors();
	}

	@HostListener('click')
	public onClick(): void {
		this.config?.click?.();
	}

	private updateColors() {
		if (this.colors.length === 1) {
			this.styles.leftStyle = { background: this.colors[0] };
			this.styles.rightStyle = { background: this.colors[0] };
		} else if (this.colors.length > 1) {
			this.styles.leftStyle = { background: this.colors[0] };
			this.styles.rightStyle = { background: this.colors[1] };
		}
	}
}